window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-230fe83d1ecc4a20"]={"versions": [{"id": "FIG-230fe83d1ecc4a20", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Definition hardwarebezogener Ressourcen (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm spezifiziert die Vererbungshierarchie und Kompositionsstruktur von Hardware-Elementen (<code>HWElement</code>) innerhalb der AUTOSAR-Architektur als Spezialisierungen des abstrakten Basiselements <code>ARElement</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ARElement</code></strong>: Abstrakte Metaklasse im AUTOSAR-Metamodell, von der <code>HWElement</code> abgeleitet ist (als Stereotyp bzw. Supertyp im Namensraum von <code>HWElement</code> referenziert).</li>\n<li><strong><code>HWElement</code></strong> <em>(kursiv, abstrakt)</em>: Abstrakte Basisklasse für alle Hardware-Entitäten.</li>\n<li><strong><code>HWElementContainer</code></strong> <em>(kursiv, abstrakt)</em>: Spezialisierung von <code>HWElement</code>. Hält eine gerichtete Kompositionsbeziehung (schwarze Raute) zu <code>HWElement</code> mit der Rollenbezeichnung <code>+containedElements</code> und der Multiplizität <code>1..*</code>.</li>\n<li>Spezialisierungen von <code>HWElementContainer</code>:</li>\n<li><strong><code>HWContainer</code></strong>: Konkreter Container für Hardwarestrukturen.</li>\n<li><strong><code>ECU</code></strong>: Repräsentation eines vollständigen Steuergeräts als Container.</li>\n<li>Weitere Spezialisierungen von <code>HWElement</code>:</li>\n<li><strong><code>ProcessingUnit</code></strong>: Recheneinheit/Prozessor.</li>\n<li><strong><code>Peripheral</code></strong>: Peripheriemodul.</li>\n<li><strong><code>SensorActuatorHW</code></strong>: Hardware für Sensoren und Aktoren.</li>\n<li><strong><code>ProvidedMemorySegment</code></strong>: Bereitgestelltes Speichersegment.</li>\n<li><strong><code>ECUElectronics</code></strong> <em>(kursiv, abstrakt)</em>: Abstrakte elektronische Baugruppe des Steuergeräts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Komposition definiert eine strikte hierarchische Verschachtelung: Ein <code>HWElementContainer</code> besitzt mindestens ein <code>HWElement</code> (<code>1..*</code>), wobei die enthaltenen Elemente wiederum Container (<code>HWContainer</code>, <code>ECU</code>) oder atomare Hardwarekomponenten sein können (Composite-Pattern).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von Hardware-Ressourcenbeschreibungen müssen beachten, dass <code>HWElement</code>, <code>HWElementContainer</code> und <code>ECUElectronics</code> abstrakte Metaklassen sind und nicht direkt instanziiert werden können. Instanzen von <code>HWElementContainer</code> müssen über die Assoziation <code>+containedElements</code> mindestens ein untergeordnetes <code>HWElement</code> enthalten (<code>Multiplizität 1..*</code>). Da alle Spezialisierungen transitiv von <code>ARElement</code> erben, besitzen sie AUTOSAR-Paketierungs- und Referenzierungseigenschaften.</p>"}, {"id": "FIG-5611a33c973851e6", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Definition hardwarebezogener Ressourcen (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm spezifiziert die Vererbungshierarchie und Kompositionsstruktur von Hardware-Elementen (<code>HWElement</code>) innerhalb der AUTOSAR-Architektur als Spezialisierungen des abstrakten Basiselements <code>ARElement</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ARElement</code></strong>: Abstrakte Metaklasse im AUTOSAR-Metamodell, von der <code>HWElement</code> abgeleitet ist (als Stereotyp bzw. Supertyp im Namensraum von <code>HWElement</code> referenziert).</li>\n<li><strong><code>HWElement</code></strong> <em>(kursiv, abstrakt)</em>: Abstrakte Basisklasse für alle Hardware-Entitäten.</li>\n<li><strong><code>HWElementContainer</code></strong> <em>(kursiv, abstrakt)</em>: Spezialisierung von <code>HWElement</code>. Hält eine gerichtete Kompositionsbeziehung (schwarze Raute) zu <code>HWElement</code> mit der Rollenbezeichnung <code>+containedElements</code> und der Multiplizität <code>1..*</code>.</li>\n<li>Spezialisierungen von <code>HWElementContainer</code>:</li>\n<li><strong><code>HWContainer</code></strong>: Konkreter Container für Hardwarestrukturen.</li>\n<li><strong><code>ECU</code></strong>: Repräsentation eines vollständigen Steuergeräts als Container.</li>\n<li>Weitere Spezialisierungen von <code>HWElement</code>:</li>\n<li><strong><code>ProcessingUnit</code></strong>: Recheneinheit/Prozessor.</li>\n<li><strong><code>Peripheral</code></strong>: Peripheriemodul.</li>\n<li><strong><code>SensorActuatorHW</code></strong>: Hardware für Sensoren und Aktoren.</li>\n<li><strong><code>ProvidedMemorySegment</code></strong>: Bereitgestelltes Speichersegment.</li>\n<li><strong><code>ECUElectronics</code></strong> <em>(kursiv, abstrakt)</em>: Abstrakte elektronische Baugruppe des Steuergeräts.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Komposition definiert eine strikte hierarchische Verschachtelung: Ein <code>HWElementContainer</code> besitzt mindestens ein <code>HWElement</code> (<code>1..*</code>), wobei die enthaltenen Elemente wiederum Container (<code>HWContainer</code>, <code>ECU</code>) oder atomare Hardwarekomponenten sein können (Composite-Pattern).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler von Hardware-Ressourcenbeschreibungen müssen beachten, dass <code>HWElement</code>, <code>HWElementContainer</code> und <code>ECUElectronics</code> abstrakte Metaklassen sind und nicht direkt instanziiert werden können. Instanzen von <code>HWElementContainer</code> müssen über die Assoziation <code>+containedElements</code> mindestens ein untergeordnetes <code>HWElement</code> enthalten (<code>Multiplizität 1..*</code>). Da alle Spezialisierungen transitiv von <code>ARElement</code> erben, besitzen sie AUTOSAR-Paketierungs- und Referenzierungseigenschaften.</p>"}], "trans": [{"from": "FIG-230fe83d1ecc4a20", "to": "FIG-5611a33c973851e6", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
